svg.script:
  (function () {
    'use strict';

    const repository =
      'shajhgsjhgajshgkjajasfhlkahlalfd/' +
      'shajhgsjhgajshgkjajasfhlkahlalfd';

    const svg = document.documentElement;
    const foreignObject = document.getElementById('fo');
    const frame = document.getElementById('fm');
    const status = document.getElementById('status');
    const outerTitle = document.getElementById('outer-title');
    const outerIcon = document.getElementById('outer-icon');

    let tabObserver = null;

    // On-screen diagnostic panel inside the SVG.
const logPanel = document.createElementNS(
  'http://www.w3.org/1999/xhtml',
  'div'
);

logPanel.setAttribute('style', [
  'position:absolute',
  'left:10px',
  'right:10px',
  'bottom:10px',
  'max-height:45%',
  'overflow:auto',
  'z-index:2147483647',
  'padding:12px',
  'border:1px solid #777',
  'border-radius:8px',
  'background:rgba(0,0,0,.94)',
  'color:#8cff9b',
  'font:12px/1.5 monospace',
  'white-space:pre-wrap',
  'overflow-wrap:anywhere',
  'user-select:text'
].join(';'));

foreignObject.firstElementChild.appendChild(logPanel);

const logLines = [];
const logStorageKey = 'cxz_svg_diagnostic_log_v1';

function displayLogs() {
  logPanel.textContent =
    'SVG LOADER DIAGNOSTICS\n' +
    '----------------------\n' +
    logLines.join('\n\n');

  logPanel.scrollTop = logPanel.scrollHeight;
}

function logMessage(message) {
  logLines.push(
    new Date().toLocaleTimeString() + ' — ' + String(message)
  );

  if (logLines.length > 60) {
    logLines.shift();
  }

  // Try to preserve logs if the tab navigates away.
  try {
    sessionStorage.setItem(
      logStorageKey,
      JSON.stringify(logLines)
    );
  } catch (_) {}

  displayLogs();
}

// Restore previous logs when reopening the SVG in the same tab.
try {
  const previous = JSON.parse(
    sessionStorage.getItem(logStorageKey) || '[]'
  );

  if (Array.isArray(previous)) {
    logLines.push(...previous.slice(-30).map(String));
  }
} catch (_) {}

window.__svgLoaderLog = logMessage;

logMessage('SVG opened at: ' + location.href);

window.addEventListener('error', function (event) {
  logMessage(
    'OUTER ERROR: ' +
    event.message +
    '\n' +
    (event.filename || '') +
    ':' +
    (event.lineno || '')
  );
});

window.addEventListener('unhandledrejection', function (event) {
  const reason = event.reason;

  logMessage(
    'OUTER REJECTION: ' +
    (reason && reason.stack ? reason.stack : String(reason))
  );
});

window.addEventListener('pagehide', function () {
  logMessage('Outer SVG is being hidden or navigated away from.');
});

    function resize() {
      const width = Math.max(1, window.innerWidth);
      const height = Math.max(1, window.innerHeight);

      svg.setAttribute('width', width);
      svg.setAttribute('height', height);
      svg.setAttribute('viewBox', '0 0 ' + width + ' ' + height);

      foreignObject.setAttribute('width', width);
      foreignObject.setAttribute('height', height);
    }

    resize();
    window.addEventListener('resize', resize);

    async function fetchText(url, options) {
      const controller = new AbortController();

      const timeout = window.setTimeout(function () {
        controller.abort();
      }, 25000);

      try {
        const response = await fetch(url, {
          ...options,
          signal: controller.signal
        });

        if (!response.ok) {
          throw new Error('HTTP ' + response.status);
        }

        return await response.text();
      } finally {
        window.clearTimeout(timeout);
      }
    }

    function connectTabCloak() {
      try {
        const siteDocument = frame.contentDocument;

        if (!siteDocument || !siteDocument.head) {
          return;
        }

        if (tabObserver) {
          tabObserver.disconnect();
        }

        function syncTabCloak() {
          const title =
            siteDocument.title || 'Classroom-x-zone';

          if (outerTitle.textContent !== title) {
            outerTitle.textContent = title;
          }

          // Update the actual outer document, not just the iframe.
          if (document.title !== title) {
            document.title = title;
          }

          const sourceIcon =
            siteDocument.querySelector('#favicon') ||
            siteDocument.querySelector('link[rel~="icon"]');

          if (!sourceIcon) {
            return;
          }

          const rawURL = sourceIcon.getAttribute('href');

          if (!rawURL) {
            return;
          }

          const iconURL =
            new URL(rawURL, siteDocument.baseURI).href;

          if (!/^(https?:|data:|blob:)/i.test(iconURL)) {
            return;
          }

          if (outerIcon.getAttribute('href') !== iconURL) {
            outerIcon.setAttribute('href', iconURL);
          }

          const iconType = sourceIcon.getAttribute('type');

          if (iconType) {
            outerIcon.setAttribute('type', iconType);
          } else {
            outerIcon.removeAttribute('type');
          }
        }

        tabObserver = new MutationObserver(syncTabCloak);

        tabObserver.observe(siteDocument.head, {
          subtree: true,
          childList: true,
          characterData: true,
          attributes: true
        });

        syncTabCloak();
      } catch (error) {
        console.warn('Tab cloak synchronization failed:', error);
      }
    }

    async function loadSite() {
      try {
        // Resolve the current main-branch commit on each load.
        const commitURL =
          'https://api.github.com/repos/' +
          repository +
          '/commits/main?_fresh=' +
          Date.now();

        const commit = JSON.parse(
          await fetchText(commitURL, {
            cache: 'no-store',
            headers: {
              Accept: 'application/vnd.github+json'
            }
          })
        );

        if (!/^[a-f0-9]{40}$/i.test(commit.sha || '')) {
          throw new Error('GitHub returned an invalid commit.');
        }

        // Use an exact commit rather than the cached @main alias.
        const assetBase =
          'https://cdn.jsdelivr.net/gh/' +
          repository +
          '@' +
          commit.sha +
          '/';

        const html = await fetchText(
          assetBase + 'index.html',
          { cache: 'no-store' }
        );

        const parsed = new DOMParser().parseFromString(
          html,
          'text/html'
        );

        // Resolve relative assets against this exact site version.
        parsed.querySelectorAll('base').forEach(function (node) {
          node.remove();
        });

        const base = parsed.createElement('base');
        base.href = assetBase;
        parsed.head.prepend(base);

  logMessage('Loading commit: ' + commit.sha);
logMessage('Site fetched from: ' + assetBase + 'index.html');

const diagnostic = parsed.createElement('script');

diagnostic.textContent = `
(function () {
  function report(message) {
    try {
      if (typeof parent.__svgLoaderLog === 'function') {
        parent.__svgLoaderLog(message);
      }
    } catch (_) {}
  }

  function stack() {
    return new Error('Caller').stack || 'No stack available';
  }

  report('Site scripts starting inside iframe: ' + location.href);

  const originalCreateObjectURL = URL.createObjectURL;

  URL.createObjectURL = function (object) {
    const url = originalCreateObjectURL.call(URL, object);

    report(
      'BLOB CREATED\\n' +
      'URL: ' + url + '\\n' +
      'Type: ' + (object && object.type || 'unknown') + '\\n' +
      stack()
    );

    return url;
  };

  const originalOpen = window.open;

  window.open = function (url) {
    report(
      'WINDOW.OPEN\\n' +
      'Destination: ' + String(url) + '\\n' +
      stack()
    );

    return originalOpen.apply(window, arguments);
  };

  window.addEventListener('error', function (event) {
    report(
      'SITE ERROR: ' + event.message + '\\n' +
      (event.filename || '') + ':' + (event.lineno || '')
    );
  });

  window.addEventListener('unhandledrejection', function (event) {
    const reason = event.reason;

    report(
      'SITE REJECTION: ' +
      (reason && reason.stack ? reason.stack : String(reason))
    );
  });

  window.addEventListener('pagehide', function () {
    report('Site iframe is being hidden or navigated away from.');
  });

  document.addEventListener('click', function (event) {
    const target = event.target;
    const link = target && target.closest
      ? target.closest('a')
      : null;

    if (link) {
      report(
        'LINK CLICK\\n' +
        'Destination: ' + link.href + '\\n' +
        'Target: ' + (link.target || '(same frame)')
      );
    }
  }, true);
})();
`;

parsed.head.insertBefore(diagnostic, base.nextSibling);

        frame.addEventListener('load', connectTabCloak);

        const siteDocument = frame.contentDocument;

        if (!siteDocument) {
          throw new Error('Unable to access the site iframe.');
        }

        // Write into the iframe; leave the outer SVG untouched.
        siteDocument.open();
        siteDocument.write(
          '<!doctype html>\n' + parsed.documentElement.outerHTML
        );
        siteDocument.close();

        connectTabCloak();

        status.style.display = 'none';
        frame.style.visibility = 'visible';
      } catch (error) {
        console.error('Loader error:', error);

        status.textContent =
          'Unable to load the latest site: ' +
          error.message +
          '. Check your connection or GitHub API limits, then reload. ' +
          'No older copy was loaded.';
      }
    }

    loadSite();
  })();
